        "PP-2": {"R1_flow": {"Q_del_m3_s": 0.006396, "margin": 0.0660, "pass": true}, "R2_head": {"H_del_m": 32.4, "margin": 0.08, "pass": true}, "R3_power": {"P_shaft_kW": 5.1429, "margin": 0.1429, "pass": true}, "R4_npsh": {"NPSHr_visc_m": 2.99, "required_m": 3.49, "margin": 0.2894, "pass": true}},
        "PP-3": {"R1_flow": {"Q_del_m3_s": 0.00779, "margin": 0.2983, "pass": true}, "R2_head": {"H_del_m": 36.0, "margin": 0.20, "pass": true}, "R3_power": {"P_shaft_kW": 7.0714, "margin": -0.1786, "pass": false}, "R4_npsh": {"NPSHr_visc_m": 3.45, "required_m": 3.95, "margin": 0.1392, "pass": true}},
        "PP-4": {"R1_flow": {"Q_del_m3_s": 0.00984, "margin": 0.6400, "pass": true}, "R2_head": {"H_del_m": 40.5, "margin": 0.35, "pass": true}, "R3_power": {"P_shaft_kW": 9.6429, "margin": -0.6071, "pass": false}, "R4_npsh": {"NPSHr_visc_m": 3.91, "required_m": 4.41, "margin": 0.0204, "pass": true}}
