        "PP-3": {"R1_flow": {"Q_del_m3_s": 0.0095, "margin": 0.5833, "pass": true}, "R2_head": {"H_del_m": 40.0, "margin": 0.3333, "pass": true}, "R3_power": {"P_shaft_kW": 5.5, "margin": 0.0833, "pass": true}, "R4_npsh": {"NPSHr_visc_m": 3.0, "required_m": 3.5, "margin": 0.2857, "pass": true}},
        "PP-4": {"R1_flow": {"Q_del_m3_s": 0.0120, "margin": 1.0000, "pass": true}, "R2_head": {"H_del_m": 45.0, "margin": 0.50, "pass": true}, "R3_power": {"P_shaft_kW": 7.5, "margin": -0.25, "pass": false}, "R4_npsh": {"NPSHr_visc_m": 3.4, "required_m": 3.9, "margin": 0.1538, "pass": true}}
      }
    },
    "reference_design": {
      "selected_model": "PP-2",
      "Q_del_m3_s": 0.006396,
      "H_del_m": 32.4,
      "P_shaft_kW": 5.1429,
      "NPSHr_visc_m": 2.99,
